fn plural(n: i64, one: &str, many: &str) -> String {
    format!("{n} {}", if n == 1 { one } else { many })
}

pub fn quiz_index(quizzes: &[QuizSummary]) -> String {
    let mut list = String::new();
    if quizzes.is_empty() {
        list.push_str(r#"<div class="empty">No quizzes yet. Create the first one.</div>"#);
    } else {
        list.push_str(r#"<ul class="quiz-list">"#);
        for s in quizzes {
            list.push_str(&format!(
                r#"<li><a class="card quiz-tile" href="/moderate/quizzes/{id}"><h3>{title}</h3><div class="meta">{count} · {active} active</div></a></li>"#,
                id = s.quiz.id,
                title = esc(&s.quiz.title),
                count = plural(s.questions, "question", "questions"),
                active = s.active,
            ));
        }
        list.push_str("</ul>");
    }
    admin_layout(
        "Quizzes",
        &format!(
            r#"<div class="page-head"><h1>Quizzes</h1><div class="buttons"><a class="btn btn--pink" href="/moderate/quizzes/new">New quiz</a></div></div>
{list}"#
        ),
    )
}

fn errors_box(errors: &[String]) -> String {
    match errors.len() {
        0 => String::new(),
        1 => format!(r#"<div class="errors" role="alert">{}</div>"#, esc(&errors[0])),
        _ => format!(
            r#"<div class="errors" role="alert"><ul>{}</ul></div>"#,
            errors.iter().map(|e| format!("<li>{}</li>", esc(e))).collect::<String>()
        ),
    }
}

