const LETTERS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZ";

pub fn letter(i: usize) -> String {
    if i < LETTERS.len() {
        (LETTERS[i] as char).to_string()
    } else {
        (i + 1).to_string()
    }
}

fn option_chips(options: &[AnswerOption]) -> String {
    options
        .iter()
        .enumerate()
        .map(|(i, o)| {
            let (class, sr) = if o.correct {
                (r#" class="is-correct""#, r#"<span class="visually-hidden"> (correct)</span>"#)
            } else {
                ("", "")
            };
            format!("<li{class}>{}. {}{sr}</li>", letter(i), esc(&o.text))
        })
        .collect()
}

