      <form method="post" action="{base}/questions/{id}/move"><input type="hidden" name="direction" value="down"><button class="btn btn--ghost btn--icon" type="submit" aria-label="Move down" title="Move down"{down_disabled}>↓</button></form>
    </div>
    <form method="post" action="{base}/questions/{id}/active" data-active-form>
      <input type="hidden" name="active" value="0">
      <label class="checkbox"><input type="checkbox" name="active" value="1"{checked}> Active</label>
      <noscript><button class="btn btn--sm btn--ghost" type="submit">Update</button></noscript>
    </form>
    <div class="buttons">
      <a class="btn btn--sm" href="{base}/questions/{id}/edit">Edit</a>
      <form method="post" action="{base}/questions/{id}/delete" onsubmit="return confirm('Delete this question?')"><button class="btn btn--sm btn--danger" type="submit">Delete</button></form>
    </div>
