    <h2>Questions</h2>
    <a class="btn" href="{base}/questions/new">Add question</a>
  </div>
  {list}
</section>
<script>
document.querySelectorAll("[data-active-form]").forEach(function (form) {{
  var box = form.querySelector("input[type=checkbox]");
  box.addEventListener("change", function () {{
    var body = new URLSearchParams();
    body.append("active", box.checked ? "1" : "0");
    box.disabled = true;
    fetch(form.action, {{ method: "POST", body: body, keepalive: true, headers: {{ "X-Requested-With": "fetch" }} }})
      .then(function (r) {{ if (!r.ok) throw new Error(r.status); }})
