/// One row of the question form, as rendered.
pub struct OptionRow {
    pub id: Option<i64>,
    pub text: String,
    pub correct: bool,
}

fn option_row(n: usize, row: &OptionRow) -> String {
    let id_field = match row.id {
        Some(id) => format!(r#"<input type="hidden" name="option_{n}_id" value="{id}">"#),
        None => String::new(),
    };
    format!(
        r#"<div class="option-row" data-option-row>{id_field}<label class="visually-hidden" for="option_{n}_text" data-text-label>Option {n}</label><input class="input" type="text" id="option_{n}_text" name="option_{n}_text" value="{text}" placeholder="Option {n}" maxlength="500"><label class="checkbox"><input type="checkbox" name="option_{n}_correct" value="1" aria-label="Option {n} is correct"{checked}> Correct</label><button class="btn btn--danger btn--icon" type="button" aria-label="Remove row" title="Remove row" data-remove-row>✕</button></div>"#,
        text = esc(&row.text),
        checked = if row.correct { " checked" } else { "" },
    )
}

pub fn question_form(
