    <textarea class="input" id="question_body" name="body" rows="3" required maxlength="1000">{body}</textarea>
  </div>
  <div class="field">
    <span class="field-label">Options</span>
    <span class="field-hint">Mark the correct options, at least one. Empty rows are skipped.</span>
  </div>
  <div class="option-rows" data-option-rows>{rows_html}</div>
  <div class="buttons" style="margin-bottom: 28px"><button class="btn btn--ghost btn--sm" type="submit" name="add_option" value="1" formnovalidate data-add-option>+ Add option</button></div>
  <div class="field">
    <input type="hidden" name="active" value="0">
    <label class="checkbox"><input type="checkbox" name="active" value="1"{checked}> Active</label>
    <span class="field-hint">Only active questions are played.</span>
