  <div class="buttons">
    <button class="btn btn--pink" type="submit">Save question</button>
    <a class="btn btn--ghost" href="{base}">Cancel</a>
  </div>
</form>
<template data-row-template>{template}</template>
<script>
(function () {{
  var rows = document.querySelector("[data-option-rows]");
  var tpl = document.querySelector("[data-row-template]");
  function renumber() {{
    rows.querySelectorAll("[data-option-row]").forEach(function (row, i) {{
      var n = i + 1;
      var label = row.querySelector("[data-text-label]");
      var text = row.querySelector("input[type=text]");
      var box = row.querySelector("input[type=checkbox]");
      var hidden = row.querySelector("input[type=hidden]");
      label.textContent = "Option " + n;
      label.htmlFor = "option_" + n + "_text";
      text.id = "option_" + n + "_text";
      text.name = "option_" + n + "_text";
      text.placeholder = "Option " + n;
      box.name = "option_" + n + "_correct";
      box.setAttribute("aria-label", "Option " + n + " is correct");
      if (hidden) hidden.name = "option_" + n + "_id";
    }});
  }}
  document.querySelector("[data-add-option]").addEventListener("click", function (e) {{
    e.preventDefault();
    rows.appendChild(tpl.content.firstElementChild.cloneNode(true));
    renumber();
    var all = rows.querySelectorAll("input[type=text]");
    all[all.length - 1].focus();
  }});
  rows.addEventListener("click", function (e) {{
    var btn = e.target.closest("[data-remove-row]");
    if (!btn) return;
    btn.closest("[data-option-row]").remove();
    renumber();
  }});
}})();
</script>"#,
            title = esc(&quiz.title),
            body = esc(body),
            checked = if active { " checked" } else { "" },
            errors = errors_box(errors),
            template = option_row(0, &OptionRow { id: None, text: String::new(), correct: false }),
        ),
    )
}

