    }
    let storage = std::env::var("QUIZZY_STORAGE").unwrap_or_else(|_| "storage".into());
    std::fs::create_dir_all(&storage).expect("create storage dir");
    let conn = db::open(&format!("{storage}/quizzy.sqlite3")).expect("open database");

    let state = AppState {
        db: Arc::new(Mutex::new(conn)),
        moderator_username: username.into(),
        moderator_password: password.into(),
    };

    let app = Router::new()
        .route("/", get(|| async { Html(views::home()) }))
        .route("/up", get(|| async { "OK" }))
        .route("/assets/quizzy.css", get(css))
        .route("/assets/Inter-latin.woff2", get(font))
        .merge(moderate_routes(state.clone()))
        .fallback(|| async { AppError::NotFound })
        .with_state(state);

    let addr = SocketAddr::from(([0, 0, 0, 0], port));
    let listener = tokio::net::TcpListener::bind(addr).await.expect("bind");
    println!("Quizzy listening on http://{addr}");
    axum::serve(listener, app)
        .with_graceful_shutdown(async {
            let ctrl_c = tokio::signal::ctrl_c();
            let mut term = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()).expect("signal");
            tokio::select! { _ = ctrl_c => {}, _ = term.recv() => {} }
        })
        .await
        .expect("serve");
}

fn moderate_routes(state: AppState) -> Router<AppState> {
    Router::new()
        .route("/moderate", get(quiz_index))
        .route("/moderate/", get(|| async { Redirect::to("/moderate") }))
        .route("/moderate/quizzes", post(quiz_create))
        .route("/moderate/quizzes/new", get(quiz_new))
        .route("/moderate/quizzes/{id}", get(quiz_show).post(quiz_update))
        .route("/moderate/quizzes/{id}/edit", get(quiz_edit))
        .route("/moderate/quizzes/{id}/delete", post(quiz_delete))
        .route("/moderate/quizzes/{id}/preview", get(preview))
        .route("/moderate/quizzes/{id}/questions", post(question_create))
        .route("/moderate/quizzes/{id}/questions/new", get(question_new))
        .route("/moderate/quizzes/{id}/questions/{qid}", post(question_update))
        .route("/moderate/quizzes/{id}/questions/{qid}/edit", get(question_edit))
        .route("/moderate/quizzes/{id}/questions/{qid}/move", post(question_move))
        .route("/moderate/quizzes/{id}/questions/{qid}/active", post(question_active))
        .route("/moderate/quizzes/{id}/questions/{qid}/delete", post(question_delete))
        .fallback(|| async { AppError::NotFound })
        .route_layer(middleware::from_fn_with_state(state, auth::require_moderator))
}

async fn css() -> impl IntoResponse {
    ([(header::CONTENT_TYPE, "text/css; charset=utf-8"), (header::CACHE_CONTROL, "public, max-age=3600")], CSS)
}

async fn font() -> impl IntoResponse {
    ([(header::CONTENT_TYPE, "font/woff2"), (header::CACHE_CONTROL, "public, max-age=31536000")], FONT)
}

fn see_other(path: String) -> Response {
    Redirect::to(&path).into_response()
}

fn unprocessable(html: String) -> Response {
    (StatusCode::UNPROCESSABLE_ENTITY, Html(html)).into_response()
}

fn load_quiz(conn: &Connection, id: i64) -> AppResult<db::Quiz> {
    db::get_quiz(conn, id)?.ok_or(AppError::NotFound)
}

// ---------- Quizzes ----------

async fn quiz_index(State(s): State<AppState>) -> AppResult {
    let quizzes = db::list_quizzes(&s.conn())?;
    Ok(Html(views::quiz_index(&quizzes)).into_response())
}

async fn quiz_new() -> Html<String> {
    Html(views::quiz_form(None, "", &[]))
}

#[derive(Deserialize)]
struct QuizParams {
    #[serde(default)]
    title: String,
}

fn validate_title(title: &str) -> Vec<String> {
    if title.trim().is_empty() { vec!["Title can't be blank".into()] } else { vec![] }
}

async fn quiz_create(State(s): State<AppState>, Form(p): Form<QuizParams>) -> AppResult {
    let errors = validate_title(&p.title);
    if !errors.is_empty() {
        return Ok(unprocessable(views::quiz_form(None, &p.title, &errors)));
    }
    let id = db::create_quiz(&s.conn(), p.title.trim())?;
    Ok(see_other(format!("/moderate/quizzes/{id}")))
}

async fn quiz_show(State(s): State<AppState>, Path(id): Path<i64>) -> AppResult {
    let conn = s.conn();
    let quiz = load_quiz(&conn, id)?;
    let questions = db::questions_for(&conn, id)?;
    Ok(Html(views::quiz_page(&quiz, &questions)).into_response())
}

async fn quiz_edit(State(s): State<AppState>, Path(id): Path<i64>) -> AppResult {
    let quiz = load_quiz(&s.conn(), id)?;
    Ok(Html(views::quiz_form(Some(&quiz), &quiz.title, &[])).into_response())
}

async fn quiz_update(State(s): State<AppState>, Path(id): Path<i64>, Form(p): Form<QuizParams>) -> AppResult {
    let conn = s.conn();
    let quiz = load_quiz(&conn, id)?;
    let errors = validate_title(&p.title);
    if !errors.is_empty() {
        return Ok(unprocessable(views::quiz_form(Some(&quiz), &p.title, &errors)));
    }
    db::update_quiz(&conn, id, p.title.trim())?;
    Ok(see_other(format!("/moderate/quizzes/{id}")))
}

async fn quiz_delete(State(s): State<AppState>, Path(id): Path<i64>) -> AppResult {
    let conn = s.conn();
    load_quiz(&conn, id)?;
    db::delete_quiz(&conn, id)?;
    Ok(see_other("/moderate".into()))
}

// ---------- Questions ----------

const MIN_ROWS: usize = 4;

fn pad_rows(mut rows: Vec<views::OptionRow>) -> Vec<views::OptionRow> {
    while rows.len() < MIN_ROWS {
        rows.push(views::OptionRow { id: None, text: String::new(), correct: false });
    }
    rows
}

async fn question_new(State(s): State<AppState>, Path(id): Path<i64>) -> AppResult {
    let quiz = load_quiz(&s.conn(), id)?;
    Ok(Html(views::question_form(&quiz, None, "", &pad_rows(vec![]), true, &[])).into_response())
}

async fn question_edit(State(s): State<AppState>, Path((id, qid)): Path<(i64, i64)>) -> AppResult {
    let conn = s.conn();
    let quiz = load_quiz(&conn, id)?;
    let q = db::get_question(&conn, id, qid)?.ok_or(AppError::NotFound)?;
    let rows = q
        .options
        .iter()
        .map(|o| views::OptionRow { id: Some(o.id), text: o.text.clone(), correct: o.correct })
        .collect();
    Ok(Html(views::question_form(&quiz, Some(q.id), &q.body, &pad_rows(rows), q.active, &[])).into_response())
}

/// The question form, parsed from `body`, `active`, and `option_N_{text,correct,id}` fields.
struct QuestionSubmission {
    body: String,
    active: bool,
    rows: Vec<views::OptionRow>,
    add_option: bool,
}

fn parse_question(fields: Vec<(String, String)>) -> QuestionSubmission {
    let mut body = String::new();
    let mut active = false;
    let mut add_option = false;
    let mut rows: BTreeMap<usize, views::OptionRow> = BTreeMap::new();
    for (k, v) in fields {
        match k.as_str() {
            "body" => body = v,
            "active" => active |= v == "1",
            "add_option" => add_option = true,
            _ => {
                let Some(rest) = k.strip_prefix("option_") else { continue };
                let Some((n, field)) = rest.split_once('_') else { continue };
                let Ok(n) = n.parse::<usize>() else { continue };
                let row = rows.entry(n).or_insert(views::OptionRow { id: None, text: String::new(), correct: false });
                match field {
                    "text" => row.text = v,
                    "correct" => row.correct = v == "1",
                    "id" => row.id = v.parse().ok(),
                    _ => {}
                }
            }
        }
    }
    QuestionSubmission { body, active, rows: rows.into_values().collect(), add_option }
}

fn validate_question(sub: &QuestionSubmission) -> (Vec<String>, Vec<db::OptionInput>) {
    let mut errors = vec![];
    if sub.body.trim().is_empty() {
        errors.push("Question can't be blank".to_string());
    }
    let options: Vec<db::OptionInput> = sub
        .rows
        .iter()
        .filter(|r| !r.text.trim().is_empty())
        .map(|r| db::OptionInput { id: r.id, text: r.text.trim().to_string(), correct: r.correct })
        .collect();
    if options.len() < 2 {
        errors.push("Add at least two options".to_string());
    }
    if !options.iter().any(|o| o.correct) {
        errors.push("Mark at least one option as correct".to_string());
    }
    (errors, options)
}

async fn save_question(s: AppState, id: i64, qid: Option<i64>, fields: Vec<(String, String)>) -> AppResult {
    let mut conn = s.conn();
    let quiz = load_quiz(&conn, id)?;
    if let Some(qid) = qid {
        db::get_question(&conn, id, qid)?.ok_or(AppError::NotFound)?;
    }
    let mut sub = parse_question(fields);
    if sub.add_option {
        // No-JS fallback for the "Add option" button: re-render with one more row.
        sub.rows.push(views::OptionRow { id: None, text: String::new(), correct: false });
        return Ok(Html(views::question_form(&quiz, qid, &sub.body, &sub.rows, sub.active, &[])).into_response());
    }
    let (errors, options) = validate_question(&sub);
    if !errors.is_empty() {
        let rows = pad_rows(sub.rows);
        return Ok(unprocessable(views::question_form(&quiz, qid, &sub.body, &rows, sub.active, &errors)));
    }
    let saved = db::save_question(&mut conn, id, qid, sub.body.trim(), sub.active, &options)?;
    Ok(see_other(format!("/moderate/quizzes/{id}#question-{saved}")))
}

async fn question_create(
    State(s): State<AppState>,
    Path(id): Path<i64>,
    Form(fields): Form<Vec<(String, String)>>,
) -> AppResult {
    save_question(s, id, None, fields).await
}

async fn question_update(
    State(s): State<AppState>,
    Path((id, qid)): Path<(i64, i64)>,
    Form(fields): Form<Vec<(String, String)>>,
) -> AppResult {
    save_question(s, id, Some(qid), fields).await
}

#[derive(Deserialize)]
struct MoveParams {
    direction: String,
}

async fn question_move(
    State(s): State<AppState>,
    Path((id, qid)): Path<(i64, i64)>,
    Form(p): Form<MoveParams>,
) -> AppResult {
    let mut conn = s.conn();
    db::get_question(&conn, id, qid)?.ok_or(AppError::NotFound)?;
    db::move_question(&mut conn, id, qid, p.direction == "up")?;
    Ok(see_other(format!("/moderate/quizzes/{id}#question-{qid}")))
}

async fn question_active(
    State(s): State<AppState>,
    Path((id, qid)): Path<(i64, i64)>,
    headers: HeaderMap,
    Form(fields): Form<Vec<(String, String)>>,
) -> AppResult {
    let conn = s.conn();
    db::get_question(&conn, id, qid)?.ok_or(AppError::NotFound)?;
    let active = fields.iter().any(|(k, v)| k == "active" && v == "1");
    db::set_active(&conn, id, qid, active)?;
    if headers.contains_key("x-requested-with") {
        return Ok(StatusCode::NO_CONTENT.into_response());
    }
    Ok(see_other(format!("/moderate/quizzes/{id}#question-{qid}")))
}

async fn question_delete(State(s): State<AppState>, Path((id, qid)): Path<(i64, i64)>) -> AppResult {
    let conn = s.conn();
    db::delete_question(&conn, id, qid)?;
    Ok(see_other(format!("/moderate/quizzes/{id}")))
}

// ---------- Preview ----------

/// Preview state lives in the URL only; nothing is stored.
#[derive(Deserialize)]
struct PreviewParams {
    step: Option<usize>,
    score: Option<usize>,
    pick: Option<i64>,
    done: Option<String>,
}

async fn preview(State(s): State<AppState>, Path(id): Path<i64>, Query(p): Query<PreviewParams>) -> AppResult {
    let conn = s.conn();
    let quiz = load_quiz(&conn, id)?;
    let questions: Vec<db::Question> = db::questions_for(&conn, id)?.into_iter().filter(|q| q.active).collect();
    let total = questions.len();
    if total == 0 {
        return Ok(Html(views::preview_empty(&quiz)).into_response());
    }
    let score = p.score.unwrap_or(0).min(total);
    if p.done.is_some() {
        return Ok(Html(views::preview_result(&quiz, score, total)).into_response());
    }
    let step = p.step.unwrap_or(0);
    if step >= total {
        return Ok(see_other(format!("/moderate/quizzes/{id}/preview?done=1&score={score}")));
    }
    let q = &questions[step];
    let picked = p.pick.filter(|pk| q.options.iter().any(|o| o.id == *pk));
    Ok(Html(views::preview_question(&quiz, q, step, total, score, picked)).into_response())
}
